const j = $('Set Model').first().json;
const today = DateTime.now().setZone('Asia/Makassar').toFormat('yyyy-MM-dd');
const SYSTEM = `You extract ONE financial transaction from an Indonesian payment screenshot (bank transfer, e-wallet, QRIS, receipt) or from a short text message. Return ONLY a JSON object. No markdown.

{
  "is_transaction": true or false,
  "type": "expense" or "income",
  "amount": integer rupiah, no dots, commas or "Rp",
  "date": "YYYY-MM-DD",
  "merchant": short name of the shop or recipient,
  "category": exactly one value from the category list,
  "notes": short remarks (include the user's caption or text remarks),
  "ref_no": reference or transaction number if visible, else "",
  "confidence": number between 0 and 1
}

Rules:
- Indonesian numbers: "1.250.000,00" means 1250000. "25rb" or "25k" means 25000. "1,5jt" means 1500000.
- amount is the total debited or received, including fees. Use the TOTAL, not a line item.
- Resolve relative dates ("kemarin", "tadi pagi") from the date given in the user message. If no date appears anywhere, use the date given in the user message.
- Money received (incoming transfer, salary) is type "income", category "Pendapatan".
- A transfer to a person with no shop context is "Keluarga & Sosial" unless the caption says otherwise.
- The user's caption or text always overrides your guess for category and notes.
- If the image is not a payment proof, or the amount cannot be read: is_transaction false, confidence 0.
- Lower the confidence when the amount or date is blurry, cropped or ambiguous.

Category list: Makanan & Minuman, Belanja Harian, Transport, Tagihan & Utilitas, Rumah Tangga, Kesehatan, Pendidikan, Hiburan, Keluarga & Sosial, Cicilan & Hutang, Tabungan & Investasi, Pendapatan, Lainnya`;
const content = [];
if (j.kind === 'image') {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  content.push({ type: 'image', source: { type: 'base64', media_type: j.mime || 'image/jpeg',
                                          data: buf.toString('base64') } });
  content.push({ type: 'text', text: `Today is ${today}. Caption from user: "${j.caption || ''}"` });
} else {
  content.push({ type: 'text', text: `Today is ${today}. Message from user: "${j.text}"` });
}
return [{ json: { body: {
  model: j.model || j.model_default || 'claude-haiku-5-5',
  max_tokens: 700, system: SYSTEM,
  messages: [{ role: 'user', content }] } } }];

const r = $json;
const ctx = $('Set Model').first().json;
const cats = ctx.categories;
const now = DateTime.now().setZone('Asia/Makassar');
const text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
let d = null;
try { d = JSON.parse(text.replace(/```json|```/g, '').trim()); } catch (e) { d = null; }
if (!d) return [{ json: { ...ctx, ok: false, errs: ['bad_json'], d: null, conf: 0 } }];
const errs = [];
if (!Number.isInteger(d.amount) || d.amount <= 0) errs.push('amount');
if (!['expense', 'income'].includes(d.type)) errs.push('type');
if (!cats.includes(d.category)) d.category = 'Lainnya';
const dt = DateTime.fromISO(d.date || '', { zone: 'Asia/Makassar' });
if (!dt.isValid || dt > now.plus({ days: 1 }) || dt < now.minus({ days: 400 })) {
 d.date = now.toISODate(); errs.push('date_fixed');
}
const conf = Number(d.confidence ?? 0);
const ok = d.is_transaction !== false && !errs.includes('amount') && !errs.includes('type') && conf >= 0.75;
const txn_id = Date.now().toString(36).slice(-5).toUpperCase();
const image_path = ctx.kind === 'image' ? `/files/images/${ctx.update_id}.jpg` : '';
return [{ json: { ...ctx, ok, errs, d, conf, txn_id, image_path } }];

