const j = $json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rp = n => 'Rp ' + Number(n).toLocaleString('id-ID');
let text = `✓ <b>${rp(j.d.amount)}</b> · ${esc(j.d.category)}\n`
 + `${esc(j.d.merchant || '-')} · ${j.d.date} · oleh ${esc(j.who)}\n`
 + `ID: <code>${j.txn_id}</code>`;
if (j.d.type === 'income') text += '\n(pemasukan)';
if (j.d.notes) text += `\nCatatan: ${esc(j.d.notes)}`;
return [{ json: { ...j, reply_text: text } }];

const j = $json;
const payload = { update_id: j.update_id, chat_id: j.chat_id, user_id: j.user_id, who: j.who,
 message_id: j.message_id, kind: j.kind, image_path: j.image_path, queue_id: j.queue_id,
 model: j.model, d: j.d, conf: j.conf, txn_id: j.txn_id };
const readable = !!(j.d && Number.isInteger(j.d.amount) && j.d.amount > 0 && j.d.is_transaction !== false);
return [{ json: { ...j, readable, conf_id: j.txn_id, payload_str: JSON.stringify(payload) } }];
